    binary_representation = bin(x)[2:]
    num_ones = binary_representation.count('1')

    # If the number of '1's is 0, return the number itself
    if num_ones == 0:
        return x

    # Otherwise, return the number of '1's as an integer in descending binary order
    return int(num_ones)

